"""Generates build/version_info.txt (the Windows version resource embedded in ApplyBot.exe).

This is what fills in Properties > Details / Task Manager / SmartScreen dialogs, so the exe
shows a real name, description and version instead of nothing. Version comes from applybot.__version__.
"""
from __future__ import annotations

import sys
from datetime import date
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT))

from applybot import __version__  # noqa: E402

OUT = ROOT / "build" / "version_info.txt"

TEMPLATE = """\
# UTF-8 - generated by tools/make_version_info.py, do not edit (change applybot/__init__.py instead)
VSVersionInfo(
  ffi=FixedFileInfo(
    filevers={tup},
    prodvers={tup},
    mask=0x3f,
    flags=0x0,
    OS=0x40004,        # VOS_NT_WINDOWS32
    fileType=0x1,      # VFT_APP
    subtype=0x0,
    date=(0, 0)
  ),
  kids=[
    StringFileInfo([
      StringTable('040904B0', [
        StringStruct('ProductName', 'ApplyBot'),
        StringStruct('FileDescription', 'ApplyBot - AI job applications'),
        StringStruct('FileVersion', '{ver}'),
        StringStruct('ProductVersion', '{ver}'),
        StringStruct('InternalName', 'ApplyBot'),
        StringStruct('OriginalFilename', 'ApplyBot.exe'),
        StringStruct('CompanyName', 'ApplyBot'),
        StringStruct('LegalCopyright', 'Copyright (c) {year} Arthur Clack'),
        StringStruct('Comments', 'Finds postings, tailors resumes and cover letters, and applies for you.')
      ])
    ]),
    VarFileInfo([VarStruct('Translation', [1033, 1200])])  # US English, Unicode
  ]
)
"""


def version_tuple(v: str) -> tuple[int, int, int, int]:
    parts = [int("".join(ch for ch in p if ch.isdigit()) or 0) for p in v.split(".")]
    return tuple((parts + [0, 0, 0, 0])[:4])  # type: ignore[return-value]


def main() -> None:
    OUT.parent.mkdir(parents=True, exist_ok=True)
    OUT.write_text(TEMPLATE.format(ver=__version__, tup=version_tuple(__version__), year=date.today().year),
                   encoding="utf-8")
    print(f"wrote {OUT} (version {__version__})")


if __name__ == "__main__":
    main()
